import{_ as t,o as r,c as s,a5 as o}from"./chunks/framework.DJo0M80U.js";const m=JSON.parse('{"title":"路由的匹配语法","description":"为了简单起见，所有的路由都省略了 component 属性，只关注 path 值。 在参数中自定义正则 当定义像 :userId 这样的参数时，我们内部使用以下的正则 ([^/]+) (至少有一个字符不是斜杠 / )来从 URL 中提取参数。这很好用，除非你需要根据参数的内容来区。","frontmatter":{"title":"路由的匹配语法","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","路由与状态管理"],"description":"为了简单起见，所有的路由都省略了 component 属性，只关注 path 值。 在参数中自定义正则 当定义像 :userId 这样的参数时，我们内部使用以下的正则 ([^/]+) (至少有一个字符不是斜杠 / )来从 URL 中提取参数。这很好用，除非你需要根据参数的内容来区。","sidebarWeight":60,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/vueRouter/路由的匹配语法.md"},"headers":[],"relativePath":"posts/Vue系统教程/04-路由与状态管理/路由的匹配语法.md","filePath":"posts/Vue系统教程/04-路由与状态管理/路由的匹配语法.md"}'),a={name:"posts/Vue系统教程/04-路由与状态管理/路由的匹配语法.md"};function p(u,e,c,n,d,h){return r(),s("div",null,[...e[0]||(e[0]=[o('<div><h1 id="路由的匹配语法" tabindex="-1">路由的匹配语法 <a class="header-anchor" href="#路由的匹配语法" aria-label="Permalink to &quot;路由的匹配语法&quot;">​</a></h1><blockquote><p>本节目标：理解“路由的匹配语法”的核心思路，并能把它用于实际开发或面试表达。 为了简单起见，所有的路由都省略了 component 属性，只关注 path 值。</p></blockquote><p><strong>在参数中自定义正则</strong> 当定义像 :userId 这样的参数时，我们内部使用以下的正则 ([^/]+) (至少有一个字符不是斜杠 / )来从 URL 中提取参数。这很好用，除非你需要根据参数的内容来区分两个路由。</p><p>想象一下，两个路由 /:orderId 和 /:productName，两者会匹配完全相同的 URL，所以我们需要一种方法来区分它们。最简单的方法就是在路径中添加一个静态部分来区分它们： const routes = [ // 匹配 /o/3549 { path: &#39;/o/:orderId&#39; }, // 匹配 /p/books { path: &#39;/p/:productName&#39; }, ] 但在某些情况下，我们并不想添加静态的 /o /p 部分。由于，orderId 总是一个数字，而 productName 可以是任何东西，所以我们可以在括号中为参数指定一个自定义的正则： const routes = [ // /:orderId -&gt; 仅匹配数字 { path: &#39;/:orderId(\\d+)&#39; }, // /:productName -&gt; 匹配其他任何内容 { path: &#39;/:productName&#39; }, ] 现在，转到 /25 将匹配 /:orderId，其他情况将会匹配 /:productName。routes 数组的顺序并不重要!</p><p>确保转义反斜杠( \\ )，就像我们对 \\d (变成\\d)所做的那样，在 JavaScript 中实际传递字符串中的反斜杠字符。</p><p><strong>可重复的参数</strong> 如果你需要匹配具有多个部分的路由，如 /first/second/third，你应该用 <em>（0 个或多个）和 +（1 个或多个）将参数标记为可重复： const routes = [ // /:chapters -&gt; 匹配 /one, /one/two, /one/two/three, 等 { path: &#39;/:chapters+&#39; }, // /:chapters -&gt; 匹配 /, /one, /one/two, /one/two/three, 等 { path: &#39;/:chapters</em>&#39; }, ]</p><p>这将为你提供一个参数数组，而不是一个字符串，并且在使用命名路由时也需要你传递一个数组： // 给定 { path: &#39;/:chapters*&#39;, name: &#39;chapters&#39; }, router.resolve({ name: &#39;chapters&#39;, params: { chapters: [] } }).href // 产生 / router.resolve({ name: &#39;chapters&#39;, params: { chapters: [&#39;a&#39;, &#39;b&#39;] } }).href // 产生 /a/b // 给定 { path: &#39;/:chapters+&#39;, name: &#39;chapters&#39; }, router.resolve({ name: &#39;chapters&#39;, params: { chapters: [] } }).href // 抛出错误，因为 <code>chapters</code> 为空</p><p>这些也可以通过在右括号后添加它们与自定义正则结合使用： const routes = [ // 仅匹配数字 // 匹配 /1, /1/2, 等 { path: &#39;/:chapters(\\d+)+&#39; }, // 匹配 /, /1, /1/2, 等 { path: &#39;/:chapters(\\d+)*&#39; }, ]</p><p><strong>Sensitive 与 strict 路由配置</strong> 默认情况下，所有路由是不区分大小写的，并且能匹配带有或不带有尾部斜线的路由。例如，路由 /users 将匹配 /users、/users/、甚至 /Users/。这种行为可以通过 strict 和 sensitive 选项来修改，它们可以既可以应用在整个全局路由上，又可以应用于当前路由上： const router = createRouter({ history: createWebHistory(), routes: [ // 将匹配 /users/posva 而非： // - /users/posva/ 当 strict: true // - /Users/posva 当 sensitive: true { path: &#39;/users/:id&#39;, sensitive: true }, // 将匹配 /users, /Users, 以及 /users/42 而非 /users/ 或 /users/42/ { path: &#39;/users/:id?&#39; }, ], strict: true, // applies to all routes })</p><p><strong>可选参数</strong> 你也可以通过使用 ? 修饰符(0 个或 1 个)将一个参数标记为可选： js const routes = [ // 匹配 /users 和 /users/posva { path: &#39;/users/:userId?&#39; }, // 匹配 /users 和 /users/42 { path: &#39;/users/:userId(\\d+)?&#39; }, ] 请注意，* 在技术上也标志着一个参数是可选的，但 ? 参数不能重复。</p><p><strong>调试</strong> 如果你需要探究你的路由是如何转化为正则的，以了解为什么一个路由没有被匹配，或者，报告一个 bug，你可以使用路径排名工具<a href="https://paths.esm.dev/?p=AAMeJSyAwR4UbFDAFxAcAGAIJXMAAA.." target="_blank" rel="noreferrer">Vue Router Path Parser (esm.dev)</a>。它支持通过 URL 分享你的路由。</p></div>',1)])])}const _=t(a,[["render",p]]);export{m as __pageData,_ as default};
